WFJ.Data.add("gossip", {
  ["8401f39e0172e6fc"] = { "%s fruga nel suo zaino ed estrae le tavolette cifrate.", "." },
  ["8403ec4c0acc1018"] = { "Questo molo collega ⟦Stormwind=Roccavento⟧ alle terre dei kaldorei passando per Auberdine, la città portuale di ⟦Darkshore=Rivafosca⟧. Se vuoi andarci, la nave arriva spesso.", "." },
  ["840f8b43730dc376"] = { "Sta' in guardia, mortale: è estremamente raro che uno dei clan minori di questa cittadella possieda un oggetto simile. La tua ricerca potrebbe durare decenni. Ti consiglio di distruggere queste bestie senza pietà.", "." },
  ["8410c6a7115262c7"] = { "Fuoco a volontà!", "." },
  ["841609e08f476ed9"] = { "Il Profanatore... devo avvertire Thrall...", "." },
  ["841ed6ea87bb2571"] = { "Se voi mortali siete tutti così vigliacchi, sarà più facile del previsto!", "." },
  ["84293ee46c69773f"] = { "È chiuso a chiave! NO!!", "." },
  ["8437cdc2cc0f6f48"] = { "Molte casse di provviste chiuse a chiave furono affondate dagli orchi nel ⟦Lake Everstill=Lago Placido⟧, a ⟦Redridge=Crestarossa⟧.", "." },
  ["844069f66fb91892"] = { "Inaspettato che siate tutti capaci di una simile organizzazione. Sia l'⟦Alliance=Alleanza⟧ sia l'⟦Horde=Orda⟧ hanno completato i preparativi per la guerra di ⟦Ahn'Qiraj=Ahn'qiraj⟧. Proprio mentre parliamo, il materiale viene spedito a ⟦Silithus=Silitus⟧ e dovrebbe arrivare tutto entro $2113w giorni. Poi toccherà a chi riassemblerà lo Scettro delle Sabbie Mutevoli percuotere il gong all'Altare dello Scarabeo e aprire i cancelli di ⟦Ahn'Qiraj=Ahn'qiraj⟧. Allora la guerra comincerà davvero!", "." },
  ["8440b9bac1aac74f"] = { "Colpisce {name} in pieno volto con un manrovescio.", "." },
  ["8440eca9843d5a88"] = { "La West Frostwolf Tower protegge la porta tra il ⟦Frostwolf Village=Villaggio dei Lupi Bianchi⟧ e la ⟦Frostwolf Keep=Rocca dei Lupi Bianchi⟧.\n\nÈ controllata dall'⟦Horde=Orda⟧.", "." },
  ["845ad8540c615afe"] = { "%s lancia un ruggito di sfida!", "." },
  ["845c558925cd6774"] = { "%s sbriciola la pietra di luna in una tazza di tè.", "." },
  ["8466e0cb96c89741"] = { "Sto per fare a pezzi {name}.", "." },
  ["846c913423739963"] = { "Lysta, evoca i prigionieri non morti.", "." },
  ["8474c47c689bcca5"] = { "Noi volere vilsegugio come famiglio. Noi dare da mangiare e trattare bene e insegnare a riportare legnetto. Tu trova stregoni in ⟦Magic Quarter=Quartiere della Magia⟧, su anello esterno di città.", "." },
  ["847c1c5beaf9fd2f"] = { "Bah! Prima di arrivare a tiro del vecchio Trollplow saresti già <ridotto/ridotta> in macerie!", "." },
  ["84876ebd8bd82c81"] = { "Ah, <sacerdote/sacerdotessa>, capiti proprio al momento giusto. Ti ringrazio.", "." },
  ["8494f610c7784fac"] = { "Sai chi sono, <fanatico/fanatica>?", "." },
  ["84a2a7e163c2dafd"] = { "L'arcano corrompe solo i deboli. Anche se non segui la via dello stregone, faresti bene a ricordarlo.", "." },
  ["84a4e6ddf424d1e3"] = { "Incisa su una tavoletta d'oro puro c'era l'incarnazione del mio rimorso, della mia vergogna, del mio rimpianto e del mio dolore. Purtroppo il ⟦Twilight's Hammer=Martello del Crepuscolo⟧ trovò la tavoletta e mi marchiò di blasfemia. Mi giustiziarono sommariamente, con la mia preghiera a Elune incompiuta. Ora il mio spirito è legato a questo mondo, incapace di trascendere nel Nether, e rinchiuso in questa gabbia come monito per tutti coloro che tradirebbero la fede del ⟦Twilight's Hammer=Martello del Crepuscolo⟧.", "." },
  ["84abdc7d1ee52156"] = { "La tua prossima scelta ti attende.\n\nTuo fratello vuole entrare nelle file del prestigioso ordine militare di cui fai già parte. Pur non avendo dubbi sul suo impegno e sulla sua lealtà, è sul suo talento e sulla sua capacità di svolgere i compiti ardui dell'ordine che nutri dei dubbi. Non hai la certezza che saprà essere all'altezza della sfida, mettendo in pericolo te e gli altri, ma sai per certo che basterebbe la tua parola per farlo entrare o tenerlo fuori.\n\nFai la tua scelta.", "." },
  ["84b24dcca3961b21"] = { "Ecco fatto! Il re dovrebbe esserne piuttosto soddisfatto, se posso dirlo.", "." },
  ["84b8f90f3dbadeef"] = { "Salve, {class}! <Benvenuto/Benvenuta> alle corse delle Distese Salate!", "." },
  ["84be44ad157017da"] = { "Hai portato rifornimenti dal nemico! Ah! Ben fatto, {name}!", "." },
  ["84d5a972f573b0c8"] = { "Troverai Fineous Darkvire oltre il Ring of Law, nella Hall of Crafting. Uccidi quel miserabile cane e recupera Ironfel.\n\nPorta Ironfel allo Shrine of Thaurissan e rimetti il martello al suo posto: nelle mani della statua eretta in mio onore.\n\nQuando sarà fatto, lo scomparto in cui ho riposto la chiave maestra si aprirà. Cosa più importante, Ironfel resterà per sempre nella mia stretta. Se tentassero di rimuovere il martello, sia la statua sia il martello andrebbero in frantumi, perduti per sempre.", "." },
  ["84da521178b7ef87"] = { "Allora, a che punto ero? Ah sì, gli orchi si lanciarono su Windsor e Windsor, be', non si mosse di un centimetro. Rimase ritto mentre lo caricavano, dieci alla volta. Tutto ciò che riuscivo a vedere era il bagliore di Ironfoe e un sacco di sangue. Andò avanti per ore, forse giorni. Non ricordo. Comunque, FINALMENTE, finì.", "." },
  ["84ee758f48c77234"] = { "Che succede? Quale forza mi attira all'Altare delle Maree!", "." },
  ["84f01892200d76f7"] = { "Che le sabbie ti divorino!", "." },
  ["84f9206345ecd570"] = { "Oh, che bel fiore laggiù...", "." },
  ["84fd9f41610b4c7f"] = { "Non poteva proprio farne a meno...", "." },
})
